	changes.fields.CreatedAt, err = lifecycle.CompareModelField(codec.Time(), before, after, assigned.fieldCreatedAt.IsSet(), func(item Manual) time.Time { return item.CreatedAt })
	if err != nil {
		return ManualChanges{}, fmt.Errorf("compare Manual.CreatedAt: %w", err)
	}
	changes.fields.UpdatedAt, err = lifecycle.CompareModelField(codec.DateTime(), before, after, assigned.fieldUpdatedAt.IsSet(), func(item Manual) temporal.DateTime { return item.UpdatedAt })
	if err != nil {
		return ManualChanges{}, fmt.Errorf("compare Manual.UpdatedAt: %w", err)
	}
